import{_ as t,a as r,o,a4 as a}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Reporting","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/reporting/index.md","filePath":"api/graphql-api/admin/reporting/index.md","lastUpdated":1783079210000}'),d={name:"api/graphql-api/admin/reporting/index.md"};function s(i,e,n,c,p,h){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h1><p>The Reporting menu returns the deep, dedicated reports behind the admin <strong>Reporting</strong> screens — <strong>Sales</strong>, <strong>Customers</strong> and <strong>Products</strong> — plus an API-only <strong>Overview</strong> convenience aggregation. Each report rolls up a chosen metric over a date window, compared against the previous equal-length window.</p><h2 id="how-a-report-is-selected-—-the-type-argument" tabindex="-1">How a report is selected — the <code>type</code> argument <a class="header-anchor" href="#how-a-report-is-selected-—-the-type-argument" aria-label="Permalink to &quot;How a report is selected — the `type` argument&quot;">​</a></h2><p>Each report query exposes several metrics, and you pick one with the <code>type</code> argument (e.g. <code>type: &quot;total-sales&quot;</code>). Omitting <code>type</code> falls back to that report&#39;s default (the first metric). The <code>statistics</code> payload is the raw aggregate for the chosen <code>type</code>, so its shape varies per metric — branch on <code>type</code> when consuming it.</p><h2 id="the-four-reports" tabindex="-1">The four reports <a class="header-anchor" href="#the-four-reports" aria-label="Permalink to &quot;The four reports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>Query</th><th><code>type</code> values</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/reporting/overview.html">Overview</a></td><td><code>statsAdminReportingOverview</code></td><td><code>total-sales</code> (default), <code>total-orders</code>, <code>total-customers</code>, <code>top-selling-products-by-revenue</code></td></tr><tr><td><a href="/api/graphql-api/admin/reporting/sales.html">Sales</a></td><td><code>statsAdminReportingSales</code></td><td><code>total-sales</code> (default) + 8 more</td></tr><tr><td><a href="/api/graphql-api/admin/reporting/customers.html">Customers</a></td><td><code>statsAdminReportingCustomers</code></td><td><code>total-customers</code> (default) + 5 more</td></tr><tr><td><a href="/api/graphql-api/admin/reporting/products.html">Products</a></td><td><code>statsAdminReportingProducts</code></td><td><code>total-sold-quantities</code> (default) + 7 more</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Overview has no matching admin screen</p><p>The admin Reporting menu goes straight to Sales / Customers / Products — there is <strong>no</strong> &quot;Overview&quot; screen in the panel. Overview is an API convenience that fetches one top-line number without calling the per-section queries.</p></div><h2 id="two-query-forms-per-report-—-stats-and-view-details" tabindex="-1">Two query forms per report — Stats and View Details <a class="header-anchor" href="#two-query-forms-per-report-—-stats-and-view-details" aria-label="Permalink to &quot;Two query forms per report — Stats and View Details&quot;">​</a></h2><p>Sales / Customers / Products each expose the same metric in two query forms:</p><table tabindex="0"><thead><tr><th>Form</th><th>Query</th><th>Shape</th><th>Mirrors</th></tr></thead><tbody><tr><td><strong>Stats</strong></td><td><code>statsAdminReporting{Sales,Customers,Products}</code></td><td>Rolled-up headline figures (charts/progress)</td><td>the panel summary</td></tr><tr><td><strong>View Details</strong></td><td><code>viewStatsAdminReporting{Sales,Customers,Products}</code></td><td><code>{ columns, records }</code> — the full row-by-row table</td><td>the panel&#39;s <strong>View Details</strong> link</td></tr></tbody></table><p><strong>Overview is summary-only</strong> — it has only the <code>statsAdminReportingOverview</code> query, no View Details. CSV <strong>Export</strong> is REST-only (binary streams aren&#39;t expressible over GraphQL) — see the <a href="/api/rest-api/admin/reporting/">REST reporting pages</a>.</p><h2 id="date-window" tabindex="-1">Date window <a class="header-anchor" href="#date-window" aria-label="Permalink to &quot;Date window&quot;">​</a></h2><p><code>start</code> / <code>end</code> (<code>YYYY-MM-DD</code>) bound the report and the <code>previous</code> baseline behind each <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>. <code>channel</code> (a channel <strong>code</strong>) scopes the figures to a single storefront channel. <code>dateRange</code> reports the two comparison windows: <code>current</code> is the window you asked for, <code>previous</code> is the equal-length window immediately before it.</p><h2 id="queries-in-this-menu" tabindex="-1">Queries in this menu <a class="header-anchor" href="#queries-in-this-menu" aria-label="Permalink to &quot;Queries in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Query</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/reporting/overview.html">Overview</a></td><td><code>statsAdminReportingOverview</code></td></tr><tr><td><a href="/api/graphql-api/admin/reporting/sales.html">Sales</a></td><td><code>statsAdminReportingSales</code> (+ <code>viewStatsAdminReportingSales</code>)</td></tr><tr><td><a href="/api/graphql-api/admin/reporting/customers.html">Customers</a></td><td><code>statsAdminReportingCustomers</code> (+ <code>viewStatsAdminReportingCustomers</code>)</td></tr><tr><td><a href="/api/graphql-api/admin/reporting/products.html">Products</a></td><td><code>statsAdminReportingProducts</code> (+ <code>viewStatsAdminReportingProducts</code>)</td></tr></tbody></table><p>Reporting is read-only and requires only an admin Bearer token (no permission gate) — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',16)]))}const u=t(d,[["render",s]]);export{m as __pageData,u as default};
